//! Host unit tests: cross-checks against `circuits/fixtures/*.json`
//! (generated by circuits/scripts/gen-fixtures.mjs) and Groth16 verification
//! of the fixture proofs with the generated `verifying_key.rs`.
//!
//! Fixtures are located relative to CARGO_MANIFEST_DIR. A missing fixture is a
//! hard failure with a "fixtures missing" message (never skipped silently).

mod common;

use anchor_lang::prelude::Pubkey;
use common::*;
use dankswap_pool::crypto::*;
use serde_json::Value;
use std::str::FromStr;

fn hex32(s: &str) -> [u8; 32] {
    hex_bytes(s).try_into().expect("32 bytes")
}

fn enc(v: &Value) -> [u8; 87] {
    hex_bytes(v.as_str().unwrap()).try_into().expect("87 bytes")
}

struct Tree {
    filled: [[u8; 32]; TREE_DEPTH],
    roots: [[u8; 32]; ROOT_HISTORY_SIZE],
    cri: u64,
    next: u64,
}
impl TreeState for Tree {
    fn filled_subtrees(&mut self) -> &mut [[u8; 32]; TREE_DEPTH] {
        &mut self.filled
    }
    fn roots(&mut self) -> &mut [[u8; 32]; ROOT_HISTORY_SIZE] {
        &mut self.roots
    }
    fn roots_ref(&self) -> &[[u8; 32]; ROOT_HISTORY_SIZE] {
        &self.roots
    }
    fn current_root_index(&mut self) -> &mut u64 {
        &mut self.cri
    }
    fn next_index(&mut self) -> &mut u64 {
        &mut self.next
    }
}
fn new_tree() -> Box<Tree> {
    let mut t = Box::new(Tree {
        filled: [[0; 32]; TREE_DEPTH],
        roots: [[0; 32]; ROOT_HISTORY_SIZE],
        cri: 0,
        next: 0,
    });
    tree_init(&mut *t);
    t
}

#[test]
fn poseidon_matches_circomlib_vectors() {
    let f = load_fixture("poseidon.json");
    let vectors = f["vectors"].as_array().unwrap();
    assert!(!vectors.is_empty());
    for v in vectors {
        let inputs: Vec<[u8; 32]> = v["inputs"]
            .as_array()
            .unwrap()
            .iter()
            .map(|x| dec_to_be32(x.as_str().unwrap()))
            .collect();
        let refs: Vec<&[u8]> = inputs.iter().map(|x| x.as_slice()).collect();
        let out = poseidon(&refs).expect("poseidon");
        assert_eq!(out, dec_to_be32(v["output"].as_str().unwrap()), "inputs {:?}", v["inputs"]);
        if let Some(h) = v["outputHex"].as_str() {
            assert_eq!(out, hex32(h));
        }
    }
}

#[test]
fn zeros_match_fixture_and_constants() {
    let f = load_fixture("zeros.json");
    let zeros = f["zeros"].as_array().unwrap();
    assert_eq!(zeros.len(), TREE_DEPTH + 1);
    let mut z = [0u8; 32];
    for (i, expected) in zeros.iter().enumerate() {
        let e = dec_to_be32(expected.as_str().unwrap());
        assert_eq!(ZEROS[i], e, "ZEROS[{i}] constant");
        assert_eq!(z, e, "computed zeros[{i}]");
        z = poseidon(&[&z, &z]).unwrap();
    }
    assert_eq!(ZEROS[TREE_DEPTH], dec_to_be32(f["emptyRoot"].as_str().unwrap()));
}

#[test]
fn merkle_single_and_pair_inserts_match_fixture() {
    let f = load_fixture("merkle.json");
    assert_eq!(f["depth"].as_u64().unwrap() as usize, TREE_DEPTH);
    let initial = dec_to_be32(f["initialRoot"].as_str().unwrap());

    // Single inserts: root after every leaf.
    let mut t = new_tree();
    assert!(tree_is_known_root(&*t, &initial));
    for s in f["singleInserts"].as_array().unwrap() {
        let leaf = dec_to_be32(s["leaf"].as_str().unwrap());
        let (root, index) = tree_append(&mut *t, &leaf).unwrap();
        assert_eq!(index, s["index"].as_u64().unwrap());
        assert_eq!(root, dec_to_be32(s["rootAfter"].as_str().unwrap()), "single insert {index}");
    }

    // Pair inserts, exactly as `transact` does (2 appends, 1 root push).
    let mut t = new_tree();
    for p in f["pairInserts"].as_array().unwrap() {
        let leaves = p["leaves"].as_array().unwrap();
        let idx = p["indices"].as_array().unwrap();
        let mut root = [0u8; 32];
        for (l, i) in leaves.iter().zip(idx) {
            let (r, index) = tree_append(&mut *t, &dec_to_be32(l.as_str().unwrap())).unwrap();
            assert_eq!(index, i.as_u64().unwrap());
            root = r;
        }
        tree_push_root(&mut *t, root);
        let expected = dec_to_be32(p["rootAfter"].as_str().unwrap());
        assert_eq!(root, expected);
        assert_eq!(t.next, p["nextIndex"].as_u64().unwrap());
        assert!(tree_is_known_root(&*t, &expected));
    }
    // Earlier roots stay known; zero and random roots are rejected.
    assert!(tree_is_known_root(&*t, &initial));
    assert!(!tree_is_known_root(&*t, &[0u8; 32]));
    assert!(!tree_is_known_root(&*t, &[7u8; 32]));
}

#[test]
fn root_history_is_a_ring_of_100() {
    let mut t = new_tree();
    let initial = ZEROS[TREE_DEPTH];
    let mut first = [0u8; 32];
    for i in 0..ROOT_HISTORY_SIZE {
        let mut leaf = [0u8; 32];
        leaf[31] = (i % 200) as u8 + 1;
        leaf[30] = (i / 200) as u8;
        let (r, _) = tree_append(&mut *t, &leaf).unwrap();
        tree_push_root(&mut *t, r);
        if i == 0 {
            first = r;
        }
    }
    // 100 pushes overwrite the initial root (slot 0) but keep the first pushed root.
    assert!(!tree_is_known_root(&*t, &initial));
    assert!(tree_is_known_root(&*t, &first));
}

#[test]
fn ext_data_hash_matches_fixture() {
    let f = load_fixture("extdata.json");
    let cases = f["cases"].as_array().unwrap();
    assert!(!cases.is_empty());
    for c in cases {
        let e = &c["extData"];
        let h = ext_data_hash(
            &Pubkey::from_str(e["recipient"].as_str().unwrap()).unwrap(),
            &Pubkey::from_str(e["relayer"].as_str().unwrap()).unwrap(),
            e["extAmount"].as_str().unwrap().parse::<i64>().unwrap(),
            e["fee"].as_str().unwrap().parse::<u64>().unwrap(),
            &enc(&e["encryptedOutput1"]),
            &enc(&e["encryptedOutput2"]),
            &enc(&e["encryptedSwapOutput"]),
        );
        assert_eq!(h, dec_to_be32(c["extDataHash"].as_str().unwrap()), "case {}", c["name"]);
        assert_eq!(h, hex32(c["extDataHashHex"].as_str().unwrap()));
        assert_eq!(h[0], 0);
    }
}

#[test]
fn mint_field_matches_fixture() {
    let f = load_fixture("mint.json");
    for m in f["mints"].as_array().unwrap() {
        let mint = Pubkey::from_str(m["mint"].as_str().unwrap()).unwrap();
        let mf = mint_field(&mint);
        assert_eq!(mf, dec_to_be32(m["mintField"].as_str().unwrap()), "{}", m["symbol"]);
        assert_eq!(mf, hex32(m["mintFieldHex"].as_str().unwrap()));
    }
    assert_eq!(dankswap_pool::NATIVE_MINT.to_string(), "So11111111111111111111111111111111111111112");
}

#[test]
fn public_amount_encoding() {
    let p = num_bigint::BigUint::from_bytes_be(&FIELD_MODULUS_BE);
    assert_eq!(
        p.to_str_radix(10),
        "21888242871839275222246405745257275088548364400416034343698204186575808495617"
    );
    // zero
    assert_eq!(public_amount(0, 0).unwrap(), [0u8; 32]);
    // positive (deposit)
    assert_eq!(public_amount(1_000_000_000, 0).unwrap(), u64_to_field(1_000_000_000));
    // private send: -fee
    let pf = |neg: u128| {
        let v = &p - num_bigint::BigUint::from(neg);
        let b = v.to_bytes_be();
        let mut out = [0u8; 32];
        out[32 - b.len()..].copy_from_slice(&b);
        out
    };
    assert_eq!(public_amount(0, 5_000_000).unwrap(), pf(5_000_000));
    // withdraw: -(500000000 + 2000000)
    assert_eq!(public_amount(-500_000_000, 2_000_000).unwrap(), pf(502_000_000));
    // positive minus fee (ext > fee)
    assert_eq!(public_amount(10, 3).unwrap(), u64_to_field(7));
    // extremes do not overflow
    assert_eq!(
        public_amount(i64::MIN, u64::MAX).unwrap(),
        pf((1u128 << 63) + u64::MAX as u128)
    );
    assert_eq!(public_amount(i64::MAX, 0).unwrap(), u64_to_field(i64::MAX as u64));
    assert_eq!(public_amount(-1, 0).unwrap(), pf(1));
    // p - 1 sanity: last byte of p is 0x01, so p - 1 ends in 0x00
    assert_eq!(pf(1)[31], 0x00);
}

/// Every proof in proofs.json must verify with the generated verifying key,
/// using public inputs re-derived the way the program derives them.
#[test]
fn groth16_fixture_proofs_verify() {
    let f = load_fixture("proofs.json");
    let cases = proof_cases(&f);
    assert!(!cases.is_empty(), "proofs.json has no proofs");
    for c in &cases {
        // Public inputs re-derived on the host (program derivation) must equal
        // the snarkjs public signals.
        let derived = c.derived_public_inputs();
        assert_eq!(derived, c.public_signals, "{}: derived public inputs != publicSignals", c.name);
        verify_groth16(&c.proof_a, &c.proof_b, &c.proof_c, &derived)
            .unwrap_or_else(|e| panic!("{}: proof rejected: {e:?}", c.name));
    }
}

#[test]
fn groth16_rejects_tampered_inputs() {
    let f = load_fixture("proofs.json");
    let cases = proof_cases(&f);
    assert!(!cases.is_empty(), "proofs.json has no proofs");
    for c in &cases {
        let good = c.derived_public_inputs();
        // Flip one byte in each public input.
        for i in 0..NR_PUBLIC_INPUTS {
            let mut bad = good;
            bad[i][31] ^= 1;
            assert!(
                verify_groth16(&c.proof_a, &c.proof_b, &c.proof_c, &bad).is_err(),
                "{}: flipped input {i} accepted",
                c.name
            );
        }
        // Wrong root.
        let mut bad = good;
        bad[0] = ZEROS[TREE_DEPTH - 1];
        assert!(verify_groth16(&c.proof_a, &c.proof_b, &c.proof_c, &bad).is_err());
        // Non-negated proof_a (client forgot spec §7 negation).
        let mut a = c.proof_a;
        let y = num_bigint::BigUint::from_bytes_be(&a[32..]);
        let q = num_bigint::BigUint::parse_bytes(
            b"21888242871839275222246405745257275088696311157297823662689037894645226208583",
            10,
        )
        .unwrap();
        let ny = (&q - y) % &q;
        let b = ny.to_bytes_be();
        a[32..].fill(0);
        a[64 - b.len()..].copy_from_slice(&b);
        assert!(verify_groth16(&a, &c.proof_b, &c.proof_c, &good).is_err());
        // Wrong ext data (different relayer fee) => different extDataHash.
        let mut bad = good;
        bad[2] = ext_data_hash(
            &c.recipient,
            &c.relayer,
            c.ext_amount,
            c.fee.wrapping_add(1),
            &c.enc1,
            &c.enc2,
            &c.enc_swap,
        );
        assert!(verify_groth16(&c.proof_a, &c.proof_b, &c.proof_c, &bad).is_err());
        // Non-canonical nullifier (n + p) is rejected by the field-size check.
        let mut bad = good;
        let n = num_bigint::BigUint::from_bytes_be(&good[4])
            + num_bigint::BigUint::from_bytes_be(&FIELD_MODULUS_BE);
        let nb = n.to_bytes_be();
        if nb.len() <= 32 {
            bad[4] = [0u8; 32];
            bad[4][32 - nb.len()..].copy_from_slice(&nb);
            assert!(verify_groth16(&c.proof_a, &c.proof_b, &c.proof_c, &bad).is_err());
        }
    }
}

#[test]
fn account_sizes_match_readme() {
    use anchor_lang::Space;
    assert_eq!(dankswap_pool::state::Config::INIT_SPACE, 66);
    assert_eq!(dankswap_pool::state::Pool::INIT_SPACE, 138);
    assert_eq!(dankswap_pool::state::MerkleTree::SIZE, 3856);
    assert_eq!(std::mem::size_of::<dankswap_pool::state::MerkleTree>(), 3856);
    assert_eq!(std::mem::offset_of!(dankswap_pool::state::MerkleTree, next_index), 3848);
}

/// Replays the fixture proof sequence through the program's tree logic: each
/// proof's root must be a known root of the on-chain tree at that point.
#[test]
fn fixture_sequence_roots_are_known_onchain() {
    let f = load_fixture("proofs.json");
    let cases = proof_cases(&f);
    let mut t = new_tree();
    for c in &cases {
        assert_eq!(t.next as usize, c.leaves_before, "{}: leavesBefore", c.name);
        assert!(tree_is_known_root(&*t, &c.root), "{}: root not known", c.name);
        let (_, i0) = tree_append(&mut *t, &c.commitments[0]).unwrap();
        let (r, i1) = tree_append(&mut *t, &c.commitments[1]).unwrap();
        assert_eq!((i0 + 1, i1 + 1), (c.leaves_before as u64 + 1, c.leaves_before as u64 + 2));
        tree_push_root(&mut *t, r);
    }
    // The swap fixture binds the SOL pool escrow PDA of this program id.
    let program_id = Pubkey::from_str(f["programId"].as_str().unwrap()).unwrap();
    assert_eq!(program_id, dankswap_pool::ID, "proofs.json generated for another program id");
    let sol_pool = Pubkey::find_program_address(&[b"pool", dankswap_pool::NATIVE_MINT.as_ref()], &program_id).0;
    let escrow = Pubkey::find_program_address(&[b"escrow", sol_pool.as_ref()], &program_id).0;
    assert_eq!(sol_pool.to_string(), f["solPool"].as_str().unwrap());
    assert_eq!(escrow.to_string(), f["solEscrow"].as_str().unwrap());
    let swap = cases.iter().find(|c| c.swap_mint.is_some()).expect("swap proof");
    assert_eq!(swap.recipient, escrow);
}
